import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Collections;
import org.simplepoint.remoting.RemoteContract;
import org.simplepoint.remoting.RemoteProvider;
import org.simplepoint.security.service.ResourceService;
import org.simplepoint.security.service.ResourceRegistrationService;
import org.simplepoint.security.resource.ResourceRegistrationException;
import org.simplepoint.plugin.rbac.resource.service.impl.ResourceRegistrationProvider;
import org.simplepoint.plugin.rbac.resource.service.properties.ResourceRegistrationProperties;
import org.simplepoint.plugin.rbac.resource.service.support.ResourceRegistrationCallerPolicy;
import org.simplepoint.platform.composition.ModuleClientPlan;

public class VerifyResourceCallerArtifacts {
  public static void main(String[] args) throws Exception {
    if (ResourceRegistrationService.class.isAssignableFrom(ResourceService.class))
      throw new AssertionError("Local management is still remotely exported");
    if (!ResourceRegistrationService.class.getAnnotation(RemoteContract.class).isolateLocalCalls())
      throw new AssertionError("Registration contract lost its mandatory local boundary");
    if (!ResourceRegistrationService.class.isAssignableFrom(ResourceRegistrationProvider.class)
        || !ResourceRegistrationProvider.class.isAnnotationPresent(RemoteProvider.class))
      throw new AssertionError("Dedicated provider missing");
    var loader = VerifyResourceCallerArtifacts.class.getClassLoader();
    for (Class<?> type : new Class<?>[] {ResourceRegistrationProvider.class, ModuleClientPlan.class}) {
      var entries = Collections.list(loader.getResources(type.getName().replace('.', '/') + ".class"));
      if (entries.size() != 1) throw new AssertionError("Missing or duplicate class " + type.getName());
    }
    for (String locale : new String[] {"en-US", "zh-CN"}) {
      var paths = Collections.list(loader.getResources(
          "META-INF/simplepoint/modules/identity/i18n/" + locale + "/resources.json"));
      if (paths.size() != 1) throw new AssertionError("Duplicate or missing translations");
      try (var input = paths.getFirst().openStream()) {
        var messages = new ObjectMapper().readTree(input);
        if (!messages.has("resources.registration.accessDenied")) throw new AssertionError("Missing error translation");
      }
    }
    try {
      new ResourceRegistrationCallerPolicy(new ResourceRegistrationProperties()).requireCaller("workflow");
      throw new AssertionError("Unconfigured artifact granted registration access");
    } catch (ResourceRegistrationException expected) {
      if (expected.code() != ResourceRegistrationException.Code.ACCESS_DENIED)
        throw new AssertionError("Wrong rejection category");
    }
    System.out.println("Installed artifacts: isolated registration, separate provider, default-deny policy, unique planning class and two error locales verified");
  }
}
